// 2. Overpressure Gauge Icon
const GaugeIcon: React.FC<{
  frame: number;
  color: string;
  intensity: number;
  needleMax: number;
}> = ({ frame, color, intensity, needleMax }) => {
  const swing = interpolate(frame, [10, 42], [-210, needleMax - 180], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const shake = frame > 42 ? Math.sin(frame * 1.5) * 1.8 : 0;
  const angle = swing + shake;

  return (
    <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", transition: "none" }}>
      <defs>
        <filter id="glow-gauge" x="-25%" y="-25%" width="150%" height="150%">
          <feGaussianBlur stdDeviation={5 * intensity} result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
      
      {/* Outer Scale Dial */}
      <circle
        cx="50"
        cy="50"
        r="38"
        fill="none"
        stroke="#ffffff"
        strokeWidth="5.5"
      />
      
      {/* Internal ticks */}
      {Array.from({ length: 9 }).map((_, i) => {
        const tickAngle = -210 + i * 30;
        const rad = (tickAngle * Math.PI) / 180;
        const x1 = 50 + Math.cos(rad) * 30;
        const y1 = 50 + Math.sin(rad) * 30;
        const x2 = 50 + Math.cos(rad) * 34;
        const y2 = 50 + Math.sin(rad) * 34;
        return (
          <line
            key={i}
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            stroke={i > 6 ? "#ff2a5f" : "#ffffff"}
            strokeWidth="2.5"
            opacity={0.8}
          />
        );
      })}
      
      {/* Red Hazard Arc */}
      <path
        d="M 76 68 A 32 32 0 0 0 76 32"
        fill="none"
        stroke="#ff2a5f"
        strokeWidth="4"
        strokeLinecap="round"
        filter="url(#glow-gauge)"
      />
      
      {/* Needle cap */}
      <circle cx="50" cy="50" r="5" fill="#ffffff" />
      
      {/* Rotating pressure needle */}
      <g transform={`rotate(${angle}, 50, 50)`} style={{ transition: "none" }}>
        <line
          x1="50"
          y1="50"
          x2="50"
          y2="18"
          stroke="#ffffff"
          strokeWidth="3.5"
          strokeLinecap="round"
        />
        <line
          x1="50"
          y1="50"
          x2="50"
          y2="18"
          stroke={color}
          strokeWidth="1.5"
          strokeLinecap="round"
          filter="url(#glow-gauge)"
          opacity={0.7}
        />
      </g>
    </svg>
  );
};

// 3. Gear Engagement Icon
const GearsIcon: React.FC<{ frame: number; color: string; intensity: number }> = ({
  frame,
  color,
  intensity,
}) => {
  const rotation = frame * 1.6;
  const largeRotation = -frame * (8 / 12) * 1.6;

  const getGearPath = (cx: number, cy: number, teeth: number, outerR: number, innerR: number) => {
    let d = "";
    const angleStep = (Math.PI * 2) / teeth;
    for (let i = 0; i < teeth; i++) {
      const angle = i * angleStep;
      const x1 = cx + Math.cos(angle - angleStep * 0.25) * innerR;
      const y1 = cy + Math.sin(angle - angleStep * 0.25) * innerR;
      const x2 = cx + Math.cos(angle - angleStep * 0.15) * outerR;
      const y2 = cy + Math.sin(angle - angleStep * 0.15) * outerR;
      const x3 = cx + Math.cos(angle + angleStep * 0.15) * outerR;
      const y3 = cy + Math.sin(angle + angleStep * 0.15) * outerR;
      const x4 = cx + Math.cos(angle + angleStep * 0.25) * innerR;
      const y4 = cy + Math.sin(angle + angleStep * 0.25) * innerR;

      if (i === 0) {
        d += `M ${x1} ${y1}`;
      } else {
        d += ` L ${x1} ${y1}`;
      }
      d += ` L ${x2} ${y2} L ${x3} ${y3} L ${x4} ${y4}`;
    }
    d += " Z";
    const holeR = innerR * 0.45;
    d += ` M ${cx} ${cy - holeR} A ${holeR} ${holeR} 0 1 0 ${cx} ${cy + holeR} A ${holeR} ${holeR} 0 1 0 ${cx} ${cy - holeR} Z`;
    return d;
  };

  return (
    <svg viewBox="0 0 130 100" style={{ width: "100%", height: "100%", transition: "none" }}>
      <defs>
        <filter id="glow-gears" x="-25%" y="-25%" width="150%" height="150%">
          <feGaussianBlur stdDeviation={5 * intensity} result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
      
      {/* Teal engagement indicators */}
      <line x1="12" y1="40" x2="32" y2="40" stroke={color} strokeWidth="2" strokeDasharray="4 4" opacity={0.5} />
      <line x1="18" y1="60" x2="42" y2="60" stroke={color} strokeWidth="2" strokeDasharray="4 4" opacity={0.5} />

      {/* Main Drive Gear */}
      <path
        d={getGearPath(85, 50, 12, 28, 22)}
        fill="#ffffff"
        transform={`rotate(${largeRotation}, 85, 50)`}
        style={{ transformOrigin: "85px 50px", transition: "none" }}
      />
      <circle cx="85" cy="50" r="5" fill={color} filter="url(#glow-gears)" opacity={0.6} />

      {/* Auxiliary Gear 1 (Top Left) */}
      <path
        d={getGearPath(42, 28, 8, 15, 11)}
        fill="#ffffff"
        transform={`rotate(${rotation}, 42, 28)`}
        style={{ transformOrigin: "42px 28px", transition: "none" }}
      />
      <circle cx="42" cy="28" r="3.5" fill={color} filter="url(#glow-gears)" opacity={0.6} />

      {/* Auxiliary Gear 2 (Bottom Left) */}
      <path
        d={getGearPath(45, 72, 8, 15, 11)}
        fill="#ffffff"
        transform={`rotate(${rotation + 22.5}, 45, 72)`}
        style={{ transformOrigin: "45px 72px", transition: "none" }}
      />
      <circle cx="45" cy="72" r="3.5" fill={color} filter="url(#glow-gears)" opacity={0.6} />

      {/* Secondary Feeder Gear */}
      <path
        d={getGearPath(22, 50, 8, 13, 9.5)}
        fill="#ffffff"
        transform={`rotate(${rotation - 10}, 22, 50)`}
        style={{ transformOrigin: "22px 50px", transition: "none" }}
      />
    </svg>
  );
};

// 4. Bottleneck Breakthrough Icon
const ArrowBurstIcon: React.FC<{ frame: number; color: string; intensity: number }> = ({
  frame,
  color,
  intensity,
}) => {
  const arrowY = interpolate(frame, [15, 45], [45, -5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const burstProgress = interpolate(frame, [26, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Explicit explosion shards
  const shards = [
    { dx: -24, dy: -18, r: -50, scale: 0.8, x0: 44, y0: 44 },
    { dx: -32, dy: 12, r: -95, scale: 0.9, x0: 41, y0: 54 },
    { dx: -18, dy: 22, r: -25, scale: 0.7, x0: 45, y0: 64 },
    { dx: 24, dy: -22, r: 65, scale: 0.8, x0: 56, y0: 44 },
    { dx: 34, dy: -6, r: 110, scale: 1.0, x0: 59, y0: 54 },
    { dx: 18, dy: 18, r: 45, scale: 0.6, x0: 55, y0: 64 },
  ];

  return (
    <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", transition: "none" }}>
      <defs>
        <filter id="glow-burst" x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation={6 * intensity} result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* Left Wall Base */}
      <rect
        x="6"
        y="50"
        width="34"
        height="22"
        rx="2"
        fill="#ffffff"
        opacity={1 - burstProgress * 0.25}
        transform={`translate(${-burstProgress * 6}, 0)`}
        style={{ transition: "none" }}
      />

      {/* Right Wall Base */}
      <rect
        x="60"
        y="50"
        width="34"
        height="22"
        rx="2"
        fill="#ffffff"
        opacity={1 - burstProgress * 0.25}
        transform={`translate(${burstProgress * 6}, 0)`}
        style={{ transition: "none" }}
      />

      {/* Erupting shards */}
      {shards.map((sh, idx) => {
        const tx = sh.dx * burstProgress;
        const ty = sh.dy * burstProgress;
        const rot = sh.r * burstProgress;
        const op = interpolate(burstProgress, [0.75, 1], [1, 0], { extrapolateLeft: "clamp" });
        
        return (
          <polygon
            key={idx}
            points={`${sh.x0},${sh.y0} ${sh.x0 + 7},${sh.y0 - 4} ${sh.x0 + 4},${sh.y0 + 6}`}
            fill="#ffffff"
            opacity={burstProgress > 0 ? op : 0}
            transform={`translate(${tx}, ${ty}) rotate(${rot}, ${sh.x0}, ${sh.y0}) scale(${sh.scale})`}
            style={{ transformOrigin: `${sh.x0}px ${sh.y0}px`, transition: "none" }}
          />
        );
      })}

      {/* Energetic pulse halo behind breakout arrow */}
      {burstProgress > 0 && (
        <circle
          cx="50"
          cy="50"
          r={28 * burstProgress}
          fill="none"
          stroke={color}
          strokeWidth={4 * (1 - burstProgress)}
          filter="url(#glow-burst)"
          opacity={1 - burstProgress}
        />
      )}

      {/* Upward Thrusting Arrow */}
      <g transform={`translate(0, ${arrowY})`} style={{ transition: "none" }}>
        <path
          d="M 50 15 L 72 42 L 59 42 L 59 75 L 41 75 L 41 42 L 28 42 Z"
          fill="#ffffff"
        />
        <path
          d="M 50 15 L 72 42 L 59 42 L 59 75 L 41 75 L 41 42 L 28 42 Z"
          fill="none"
          stroke={color}
          strokeWidth="2.5"
          filter="url(#glow-burst)"
          opacity={0.8}
        />
      </g>
    </svg>
  );
};

