// Column Controller holding Spotlight, Icon rendering, wet reflection, and Label
const IconColumn: React.FC<{
  index: number;
  id: string;
  active: boolean;
  highlightColor: string;
  frame: number;
  width: number;
  height: number;
  horizon: number;
  iconSize: number;
  glowIntensity: number;
  spotlightIntensity: number;
  needleAngleMax: number;
}> = ({
  index,
  id,
  active,
  highlightColor,
  frame,
  width,
  height,
  horizon,
  iconSize,
  glowIntensity,
  spotlightIntensity,
  needleAngleMax,
}) => {
  // Cascaded launch/stagger delay
  const launchDelay = index * 6;
  const iconFrame = Math.max(0, frame - launchDelay);

  // Responsive pop physics using spring
  const scale = spring({
    frame: iconFrame,
    fps: 30,
    config: { damping: 11, mass: 0.85 },
  });

  const opacity = interpolate(iconFrame, [0, 16], [0, 1], { extrapolateRight: "clamp" });

  const renderIcon = (f: number) => {
    switch (id) {
      case "chain":
        return <ChainIcon frame={f} color={highlightColor} intensity={glowIntensity} />;
      case "gauge":
        return <GaugeIcon frame={f} color={highlightColor} intensity={glowIntensity} needleMax={needleAngleMax} />;
      case "gears":
        return <GearsIcon frame={f} color={highlightColor} intensity={glowIntensity} />;
      case "burst":
        return <ArrowBurstIcon frame={f} color={highlightColor} intensity={glowIntensity} />;
      case "cycle":
        return <LoopArrowsIcon frame={f} color={highlightColor} intensity={glowIntensity} />;
      default:
        return null;
    }
  };

  return (
    <div
      style={{
        position: "absolute",
        left: `${(index * 100) / 5}%`,
        width: `${100 / 5}%`,
        height: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        transition: "none",
      }}
    >
      {/* Volumetric Spotlight Cone from upper grid */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: "50%",
          transform: "translateX(-50%)",
          width: 320,
          height: horizon,
          pointerEvents: "none",
          transition: "none",
        }}
        viewBox="0 0 200 600"
        preserveAspectRatio="none"
      >
        <defs>
          <linearGradient id={`spotlight-grad-${index}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={highlightColor} stopOpacity={0.16 * spotlightIntensity} />
            <stop offset="35%" stopColor={highlightColor} stopOpacity={0.06 * spotlightIntensity} />
            <stop offset="100%" stopColor={highlightColor} stopOpacity="0" />
          </linearGradient>
        </defs>
        <path
          d="M 88 0 L 112 0 L 200 600 L 0 600 Z"
          fill={`url(#spotlight-grad-${index})`}
        />
      </svg>

      {/* Original Icon Base */}
      <div
        style={{
          position: "absolute",
          top: horizon - iconSize - 10,
          width: iconSize,
          height: iconSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity,
          transform: `scale(${scale})`,
          transition: "none",
        }}
      >
        {renderIcon(iconFrame)}
      </div>

      {/* Floor Mirror Reflection */}
      <div
        style={{
          position: "absolute",
          top: horizon + 10,
          width: iconSize,
          height: iconSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: opacity * 0.22,
          transform: `scale(${scale}) scaleY(-1)`,
          filter: "blur(5px)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {renderIcon(iconFrame)}
      </div>
    </div>
  );
};

// Continuous Floating Dust / Specks in Dark Studio Space
const DustParticles: React.FC<{
  count: number;
  width: number;
  height: number;
  frame: number;
  durationInFrames: number;
}> = ({ count, width, height, frame, durationInFrames }) => {
  return (
    <>
      {Array.from({ length: count }).map((_, i) => {
        const seedX = random(`dust-x-${i}`);
        const seedY = random(`dust-y-${i}`);
        const seedSize = random(`dust-size-${i}`);
        
        const initialX = seedX * width;
        const initialY = seedY * height;
        const size = seedSize * 3 + 1.2;
        
        // Loop float up speed
        const speedMultiplier = (0.2 + seedSize * 0.8) * 35;
        const progress = (frame / durationInFrames) * speedMultiplier;
        const y = (initialY - progress + height) % height;
        
        // Gentle horizontal drift
        const drift = Math.sin((frame * 0.012) + (seedX * 100)) * 14;
        const x = (initialX + drift) % width;
        
        const particleOpacity = interpolate(
          Math.sin((frame * 0.045) + (seedY * 50)),
          [-1, 1],
          [0.15, 0.45]
        );
        
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              width: size,
              height: size,
              borderRadius: "50%",
              backgroundColor: "#ffffff",
              boxShadow: "0 0 5px rgba(255,255,255,0.7)",
              opacity: particleOpacity,
              pointerEvents: "none",
              transition: "none",
            }}
          />
        );
      })}
    </>
  );
};

